const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const strip = s => s.replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
const cleanZh = s => String(s)
  .replaceAll('暴露任务','发现待办').replaceAll('暴露前一类信息','呈现平台信息').replaceAll('暴露','呈现')
